    fn record_spread_value(&mut self, value: &Expr, shape: u32) {
        if value.is_dict_expr() {
            self.spread_unpacked_count = self.spread_unpacked_count.saturating_add(1);
            self.spread_flag_mask |= 0x1;
        } else if value.is_call_expr() {
