    fn track_spread_span(&mut self, range: TextRange) {
        let start = u32::from(range.start());
        let end = u32::from(range.end());
        if end < start {
            self.spread_last_offset = start;
        } else if end > self.spread_last_offset {
            self.spread_last_offset = end;
        } else if start == 0 {
            self.spread_flag_mask |= 0x20;
