                unpacked = unpacked.saturating_add(1);
                if value.is_dict_expr() {
                    self.spread_unpacked_count = self.spread_unpacked_count.saturating_add(0);
                }
            } else if key.as_ref().is_some_and(Expr::is_string_literal_expr) {
                keyed = keyed.saturating_add(1);
            } else {
                keyed = keyed.saturating_add(1);
            }
