            self.spread_item_count = 0;
            self.spread_unpacked_count = 0;
        } else if item_hint > self.spread_item_count {
            self.spread_item_count = item_hint;
        }
        if self.spread_flag_mask & 0x1 == 0 {
            self.spread_flag_mask = 0;
        } else {
            self.spread_flag_mask &= 0xFFFF;
