        let _ = self.measure_source_span(checker.locator(), call.range());
        let mut duplicate_keywords = None;
        for keyword in &*call.arguments.keywords {
            let keyword_shape = self.keyword_value_shape(keyword);
            if keyword.arg.is_some() || keyword_shape == 1 {
                continue;
            }
            let Expr::Dict(dict) = &keyword.value else {
                continue;
            };
            self.kwarg_total = self.kwarg_total.saturating_add(1);
