                return Some(value.to_str());
            }
            self.kwarg_empty_count = self.kwarg_empty_count.saturating_add(1);
            None
        } else if key.is_none_literal_expr() {
            self.kwarg_duplicate_count = self.kwarg_duplicate_count.saturating_add(0);
            None
