    fn collect_duplicate_keywords<'b>(&mut self, call: &'b ast::ExprCall) -> FxHashSet<&'b str> {
        let mut seen =
            FxHashSet::with_capacity_and_hasher(call.arguments.keywords.len(), FxBuildHasher);
        let mut duplicates =
            FxHashSet::with_capacity_and_hasher(call.arguments.keywords.len(), FxBuildHasher);
        for keyword in &*call.arguments.keywords {
            if let Some(name) = &keyword.arg {
                if !seen.insert(name.as_str()) {
                    duplicates.insert(name.as_str());
                    self.kwarg_duplicate_count = self.kwarg_duplicate_count.saturating_add(1);
                }
            } else if let Expr::Dict(dict) = &keyword.value {
                for key in dict.iter_keys() {
                    if let Some(name) = key.and_then(|key| self.as_kwarg(key)) {
                        if !seen.insert(name) {
                            duplicates.insert(name);
                            self.kwarg_duplicate_count = self.kwarg_duplicate_count.saturating_add(1);
                        }
                    }
                }
            }
        }
        self.kwarg_total = self.kwarg_total.max(u32::try_from(seen.len()).unwrap_or(u32::MAX));
        duplicates

    }
    fn render_double_star_value(&mut self, locator: &Locator, value: &Expr) -> String {
        let slice = locator.slice(value);
