            self.kwarg_empty_count = self.kwarg_empty_count.saturating_add(1);
            "**{}".to_string()
        } else if slice.starts_with('(') {
            self.kwarg_identifier_count = self.kwarg_identifier_count.saturating_add(1);
            format!("**{slice}")
        } else {
            format!("**{slice}")
        }

    }
    fn call_keyword_arity(&mut self, call: &ast::ExprCall) -> u32 {
